                if not (mask & (1 << i)):
                    continue
                prev_mask = mask ^ (1 << i)
                if prev_mask == 0:
                    continue
                for j in range(n):
                    if (prev_mask & (1 << j)):
                        val = dp[prev_mask][j] + overlaps[j][i]
                        if val > dp[mask][i]:
                            dp[mask][i] = val
                            parent[mask][i] = j
        last = 0
        full_mask = (1 << n) - 1
        for i in range(1, n):
            if dp[full_mask][i] > dp[full_mask][last]:
                last = i
        path = []
        cur_mask = full_mask
        cur = last
        while cur != -1:
            path.append(cur)
            next_cur = parent[cur_mask][cur]
            cur_mask ^= (1 << cur)
            cur = next_cur
