class Solution {
public:
    string shortestSuperstring(vector<string>& words) {
        int n = words.size();
        vector<vector<int>> overlaps(n, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i != j) {
                    for (int k = min(words[i].size(), words[j].size()); k > 0; --k) {
                        if (words[i].substr(words[i].size() - k) == words[j].substr(0, k)) {
                            overlaps[i][j] = k;
                            break;
                        }
                    }
                }
            }
        }
        vector<vector<int>> dp(1 << n, vector<int>(n, 0));
        vector<vector<int>> parent(1 << n, vector<int>(n, -1));
        for (int mask = 1; mask < (1 << n); ++mask) {
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) continue;
                int prev = mask ^ (1 << i);
                if (prev == 0) continue;
                for (int j = 0; j < n; ++j) {
                    if (prev & (1 << j)) {
                        int val = dp[prev][j] + overlaps[j][i];
                        if (val > dp[mask][i]) {
                            dp[mask][i] = val;
                            parent[mask][i] = j;
                        }
                    }
                }
            }
        }
        int full = (1 << n) - 1;
        int last = 0;
        for (int i = 1; i < n; ++i) {
            if (dp[full][i] > dp[full][last]) last = i;
        }
        vector<int> path;
        int cur_mask = full, cur = last;
        while (cur != -1) {
            path.push_back(cur);
            int next_cur = parent[cur_mask][cur];
            cur_mask ^= (1 << cur);
            cur = next_cur;
        }
        reverse(path.begin(), path.end());
        string res = words[path[0]];
        for (int idx = 1; idx < path.size(); ++idx) {
            int i = path[idx - 1], j = path[idx];
            res += words[j].substr(overlaps[i][j]);
        }
        return res;
    }
};

class Solution {
    public String shortestSuperstring(String[] words) {
        int n = words.length;
        int[][] overlaps = new int[n][n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i != j) {
                    for (int k = Math.min(words[i].length(), words[j].length()); k > 0; --k) {
                        if (words[i].endsWith(words[j].substring(0, k))) {
                            overlaps[i][j] = k;
                            break;
                        }
                    }
                }
            }
        }
        int[][] dp = new int[1 << n][n];
        int[][] parent = new int[1 << n][n];
        for (int[] row : parent) Arrays.fill(row, -1);
        for (int mask = 1; mask < (1 << n); ++mask) {
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) == 0) continue;
                int prev = mask ^ (1 << i);
                if (prev == 0) continue;
                for (int j = 0; j < n; ++j) {
                    if ((prev & (1 << j)) != 0) {
                        int val = dp[prev][j] + overlaps[j][i];
                        if (val > dp[mask][i]) {
                            dp[mask][i] = val;
                            parent[mask][i] = j;
                        }
                    }
                }
            }
        }
        int full = (1 << n) - 1;
        int last = 0;
        for (int i = 1; i < n; ++i) {
            if (dp[full][i] > dp[full][last]) last = i;
        }
        List<Integer> path = new ArrayList<>();
        int curMask = full, cur = last;
        while (cur != -1) {
            path.add(cur);
            int nextCur = parent[curMask][cur];
            curMask ^= (1 << cur);
            cur = nextCur;
        }
        Collections.reverse(path);
        StringBuilder res = new StringBuilder(words[path.get(0)]);
        for (int idx = 1; idx < path.size(); ++idx) {
            int i = path.get(idx - 1), j = path.get(idx);
            res.append(words[j].substring(overlaps[i][j]));
        }
        return res.toString();
    }
}

var shortestSuperstring = function(words) {
    const n = words.length;
    const overlaps = Array.from({ length: n }, () => new Int32Array(n));
    for (let i = 0; i < n; ++i) {
        for (let j = 0; j < n; ++j) {
            if (i !== j) {
                for (let k = Math.min(words[i].length, words[j].length); k > 0; --k) {
                    if (words[i].endsWith(words[j].substring(0, k))) {
                        overlaps[i][j] = k;
                        break;
                    }
                }
            }
        }
    }
    const dp = Array.from({ length: 1 << n }, () => new Int32Array(n));
    const parent = Array.from({ length: 1 << n }, () => new Int32Array(n).fill(-1));
    for (let mask = 1; mask < (1 << n); ++mask) {
        for (let i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) continue;
            const prev = mask ^ (1 << i);
            if (prev === 0) continue;
            for (let j = 0; j < n; ++j) {
                if (prev & (1 << j)) {
                    const val = dp[prev][j] + overlaps[j][i];
                    if (val > dp[mask][i]) {
                        dp[mask][i] = val;
                        parent[mask][i] = j;
                    }
                }
            }
        }
    }
    const full = (1 << n) - 1;
    let last = 0;
    for (let i = 1; i < n; ++i) {
        if (dp[full][i] > dp[full][last]) last = i;
    }
    const path = [];
    let curMask = full, cur = last;
    while (cur !== -1) {
        path.push(cur);
        const nextCur = parent[curMask][cur];
        curMask ^= (1 << cur);
        cur = nextCur;
    }
    path.reverse();
    let res = words[path[0]];
    for (let idx = 1; idx < path.length; ++idx) {
        const i = path[idx - 1], j = path[idx];
        res += words[j].substring(overlaps[i][j]);
    }
    return res;
};
